command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -u
cd ~/Upload-Assistant-wastaken
echo state:
podman inspect upload-assistant-wastaken --format 'status={{.State.Status}} pid={{.State.Pid}} exit={{.State.ExitCode}} error={{.State.Error}} restart={{.RestartCount}}' 2>&1 || true
echo auth:
podman exec upload-assistant-wastaken python3 -c 'from web_ui import auth; u=auth.load_user(); print("user_present="+str(bool(u))+" username="+str((u or {}).get("username")))' 2>&1 || true
echo logs:
podman logs --tail 100 upload-assistant-wastaken 2>&1 || true
echo ports:
for p in 12347 12345; do code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 5 http://127.0.0.1:$p/api/health || true); echo "$p=$code"; done
REMOTE
